const VALID_GENRES = [
  'Office Equipment & Technology',
  'Food & Drink',
  'Telecommunications & Internet',
  'Healthcare',
  'Education',
  'Tobacco & E-cigarettes',
  'Charity & Nonprofit',
  'Fashion',
  'Retail',
  'Professional & Business Services',
  'Property & Construction',
  'Agencies',
  'Entertainment',
  'Transportation & Logistics',
  'Consumer Electronics',
  'Travel & Tourism',
  'Financial',
  'Utilities & Energy',
  'Leisure & Hospitality',
  'Media & Publishing',
  'Government & Public Sector',
  'Cosmetics & Personal Care',
  'Home & Garden',
  'Automotive',
  'Manufacturing & Industrial',
  'Household Consumer Goods'
];

const client = $('Loop Clients').first().json;
const run = $('Create Run').first().json;
const results = [];
const errors = [];

for (const item of $input.all()) {
  const url = (item.json.URL || '').trim();
  const genre = (item.json.Genre || '').trim();

  if (!url) {
    errors.push({ url: '', genre, reason: 'Missing URL', client_id: client.id, run_id: run.id });
    continue;
  }

  if (!genre) {
    errors.push({ url, genre: '', reason: 'Missing genre', client_id: client.id, run_id: run.id });
    continue;
  }

  if (!VALID_GENRES.includes(genre)) {
    errors.push({ url, genre, reason: `Invalid genre: ${genre}`, client_id: client.id, run_id: run.id });
    continue;
  }

  let normalizedUrl = url;
  try {
    const parsed = new URL(url);
    normalizedUrl = parsed.href;
  } catch (e) {
    errors.push({ url, genre, reason: 'Invalid URL format', client_id: client.id, run_id: run.id });
    continue;
  }

  results.push({
    json: {
      homepage_url: normalizedUrl,
      genre,
      client_id: client.id,
      run_id: run.id,
      client_name: client.name,
      max_stories_per_genre: client.max_stories_per_genre || 6,
      max_stories_per_day: client.max_stories_per_day || 60
    }
  });
}

$workflow.setStaticData('validation_errors', errors);

return results.slice(0, 200);

const cheerio = require('cheerio');

const item = $input.first().json;
const html = item.data || item.body || '';
const homepageUrl = $('Loop Homepages').item.json.homepage_url;
const genre = $('Loop Homepages').item.json.genre;
const clientId = $('Loop Homepages').item.json.client_id;
const runId = $('Loop Homepages').item.json.run_id;

if (!html || typeof html !== 'string' || html.length < 500) {
  return [{
    json: {
      candidates: [],
      homepage_url: homepageUrl,
      genre,
      client_id: clientId,
      run_id: runId,
      error: 'Empty or invalid HTML'
    }
  }];
}

const $ = cheerio.load(html);
const baseUrl = new URL(homepageUrl);
const baseDomain = baseUrl.hostname.replace('www.', '');

const EXCLUDED_PATHS = [
  '/tag/', '/tags/', '/author/', '/authors/', '/about/', '/about-us/',
  '/login/', '/signin/', '/signup/', '/subscribe/', '/subscription/',
  '/privacy/', '/privacy-policy/', '/terms/', '/terms-of-service/',
  '/jobs/', '/careers/', '/contact/', '/sitemap/', '/search/',
  '/category/', '/categories/', '/archive/', '/rss/', '/feed/',
  '/account/', '/profile/', '/settings/', '/help/', '/faq/',
  '/advertise/', '/advertising/', '/media-kit/', '/press/',
  '/newsletter/', '/podcasts/', '/videos/', '/webinars/'
];

const EXCLUDED_EXT = ['.pdf', '.doc', '.docx', '.xls', '.xlsx', '.ppt', '.jpg', '.jpeg', '.png', '.gif', '.svg', '.webp', '.zip', '.mp3', '.mp4'];

const TRACKING_PARAMS = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'fbclid', 'gclid', 'msclkid', 'ref'];

const candidates = [];
const seenUrls = new Set();

$('a[href]').each((i, el) => {
  try {
    let href = $(el).attr('href');
    if (!href || href.startsWith('#') || href.startsWith('javascript:') || href.startsWith('mailto:') || href.startsWith('tel:')) return;

    let fullUrl;
    try {
      fullUrl = new URL(href, homepageUrl);
    } catch (e) {
      return;
    }

    const linkDomain = fullUrl.hostname.replace('www.', '');
    if (linkDomain !== baseDomain) return;

    const path = fullUrl.pathname.toLowerCase();
    for (const excl of EXCLUDED_PATHS) {
      if (path.includes(excl)) return;
    }
    for (const ext of EXCLUDED_EXT) {
      if (path.endsWith(ext)) return;
    }

    for (const param of TRACKING_PARAMS) {
      fullUrl.searchParams.delete(param);
    }

    const cleanUrl = fullUrl.href;
    if (seenUrls.has(cleanUrl)) return;
    seenUrls.add(cleanUrl);

    if (cleanUrl === homepageUrl || cleanUrl === homepageUrl + '/') return;

    let articleScore = 0;
    const datePattern = /\/(20[0-9]{2})[\/\-](0[1-9]|1[0-2])[\/\-](0[1-9]|[12][0-9]|3[01])/;
    if (datePattern.test(path)) articleScore += 3;

    const pathParts = path.split('/').filter(p => p.length > 0);
    if (pathParts.length >= 2) articleScore += 1;

    const slug = pathParts[pathParts.length - 1] || '';
    if (slug.length > 20) articleScore += 2;

    if (path.includes('/news/') || path.includes('/article/') || path.includes('/story/') || path.includes('/post/') || path.includes('/blog/')) {
      articleScore += 2;
    }

    const linkText = $(el).text().trim().substring(0, 200);

    let nearbyTimestamp = null;
    const timeEl = $(el).parent().find('time').first();
    if (timeEl.length) {
      nearbyTimestamp = timeEl.attr('datetime') || timeEl.text();
    }

    if (articleScore >= 2) {
      candidates.push({
        url: cleanUrl,
        link_text: linkText,
        article_score: articleScore,
        nearby_timestamp: nearbyTimestamp
      });
    }
  } catch (e) {}
});

candidates.sort((a, b) => b.article_score - a.article_score);

return [{
  json: {
    candidates: candidates.slice(0, 100),
    homepage_url: homepageUrl,
    genre,
    client_id: clientId,
    run_id: runId,
    candidates_found: candidates.length
  }
}];

const input = $input.first().json;
const candidates = input.candidates || [];

if (candidates.length === 0) {
  return [{
    json: {
      ...input,
      coverage_warning: `No candidates from ${input.homepage_url}`,
      flattened_candidates: []
    }
  }];
}

const results = candidates.map(c => ({
  json: {
    article_url: c.url,
    article_score: c.article_score,
    nearby_timestamp: c.nearby_timestamp,
    link_text: c.link_text,
    homepage_url: input.homepage_url,
    genre: input.genre,
    client_id: input.client_id,
    run_id: input.run_id
  }
}));

return results;

const allCandidates = [];
const items = $input.all();

for (const item of items) {
  if (item.json.article_url) {
    allCandidates.push(item);
  }
}

const seenUrls = new Set();
const unique = [];

for (const item of allCandidates) {
  if (!seenUrls.has(item.json.article_url)) {
    seenUrls.add(item.json.article_url);
    unique.push(item);
  }
}

return unique;

const cheerio = require('cheerio');
const crypto = require('crypto');

const item = $input.first();
const html = item.json.data || item.json.body || '';
const articleUrl = $('Batch (5)').item.json.article_url;
const genre = $('Batch (5)').item.json.genre;
const clientId = $('Batch (5)').item.json.client_id;
const runId = $('Batch (5)').item.json.run_id;

if (!html || typeof html !== 'string' || html.length < 500) {
  return [{
    json: {
      skip: true,
      skip_reason: 'Empty or short response',
      url: articleUrl,
      genre,
      client_id: clientId,
      run_id: runId
    }
  }];
}

const $ = cheerio.load(html);

let canonicalUrl = $('link[rel="canonical"]').attr('href') || $('meta[property="og:url"]').attr('content') || articleUrl;
if (canonicalUrl && !canonicalUrl.startsWith('http')) {
  try {
    canonicalUrl = new URL(canonicalUrl, articleUrl).href;
  } catch (e) {
    canonicalUrl = articleUrl;
  }
}

const sourceName = $('meta[property="og:site_name"]').attr('content') || $('meta[name="application-name"]').attr('content') || new URL(canonicalUrl).hostname.replace('www.', '');

const title = $('meta[property="og:title"]').attr('content') || $('meta[name="title"]').attr('content') || $('title').text().trim().split('|')[0].trim() || $('h1').first().text().trim();

const paywallSel = ['.paywall', '.subscription-required', '[data-paywall]', '.premium-content', '.subscriber-only', '.locked-content'];
let isPaywalled = false;
for (const sel of paywallSel) {
  if ($(sel).length > 0) {
    isPaywalled = true;
    break;
  }
}

let publishDate = null;
let publishDateSource = null;
let confidence = 0;

$('script[type="application/ld+json"]').each((i, el) => {
  if (publishDate) return;
  try {
    const data = JSON.parse($(el).html());
    const items = Array.isArray(data) ? data : [data];
    for (const itm of items) {
      if (['NewsArticle', 'Article', 'BlogPosting', 'WebPage'].includes(itm['@type'])) {
        if (itm.datePublished) {
          publishDate = itm.datePublished;
          publishDateSource = 'jsonld_published';
          confidence = 0.95;
          break;
        }
        if (itm.dateModified) {
          publishDate = itm.dateModified;
          publishDateSource = 'jsonld_modified';
          confidence = 0.85;
          break;
        }
      }
    }
  } catch (e) {}
});

if (!publishDate) {
  const ogDate = $('meta[property="article:published_time"]').attr('content');
  if (ogDate) {
    publishDate = ogDate;
    publishDateSource = 'opengraph';
    confidence = 0.90;
  }
}

if (!publishDate) {
  const metaSel = ['meta[name="pubdate"]', 'meta[name="date"]', 'meta[name="DC.date"]', 'meta[name="DC.date.issued"]', 'meta[itemprop="datePublished"]', 'meta[name="article:published"]'];
  for (const sel of metaSel) {
    const val = $(sel).attr('content');
    if (val) {
      publishDate = val;
      publishDateSource = 'meta';
      confidence = 0.80;
      break;
    }
  }
}

if (!publishDate) {
  const timeEl = $('time[datetime]').first();
  if (timeEl.length) {
    publishDate = timeEl.attr('datetime');
    publishDateSource = 'time_element';
    confidence = 0.70;
  }
}

if (!publishDate) {
  const urlMatch = canonicalUrl.match(/\/(20[0-9]{2})\/(0[1-9]|1[0-2])\/(0[1-9]|[12][0-9]|3[01])/);
  if (urlMatch) {
    publishDate = `${urlMatch[1]}-${urlMatch[2]}-${urlMatch[3]}`;
    publishDateSource = 'url_pattern';
    confidence = 0.50;
  }
}

$('script, style, nav, header, footer, aside, .ad, .advertisement, .social-share, .related-articles, .comments, .sidebar, noscript').remove();

let articleBody = '';
const contentSel = ['article', '[itemprop="articleBody"]', '.article-body', '.article-content', '.post-content', '.entry-content', '.story-body', 'main', '.content'];
for (const sel of contentSel) {
  const content = $(sel).first();
  if (content.length && content.text().trim().length > 300) {
    articleBody = content.text().trim();
    break;
  }
}

if (!articleBody || articleBody.length < 300) {
  const paragraphs = [];
  $('p').each((i, el) => {
    const text = $(el).text().trim();
    if (text.length > 40) paragraphs.push(text);
  });
  articleBody = paragraphs.join('\n\n');
}

if (articleBody.length < 300) isPaywalled = true;

const dedupeKey = crypto.createHash('sha256').update(canonicalUrl).digest('hex').substring(0, 64);
const titleNormalized = title ? title.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim() : '';
const contentFingerprint = crypto.createHash('sha256').update(articleBody.substring(0, 1000)).digest('hex').substring(0, 64);

return [{
  json: {
    url: articleUrl,
    canonical_url: canonicalUrl,
    genre,
    client_id: clientId,
    run_id: runId,
    source_name: sourceName,
    original_title: title,
    article_body: articleBody,
    word_count: articleBody.split(/\s+/).length,
    publish_date: publishDate,
    publish_date_source: publishDateSource,
    publish_date_confidence: confidence,
    is_paywalled: isPaywalled,
    dedupe_key: dedupeKey,
    title_normalized: titleNormalized,
    content_fingerprint: contentFingerprint,
    skip: false
  }
}];

const item = $input.first().json;

if (item.skip) return [{ json: item }];

if (item.is_paywalled) {
  return [{ json: { ...item, skip: true, skip_reason: 'Paywalled or blocked' } }];
}

if (!item.publish_date) {
  return [{ json: { ...item, skip: true, skip_reason: 'Unknown publish date - MANDATORY SKIP' } }];
}

let pubDate;
try {
  pubDate = new Date(item.publish_date);
  if (isNaN(pubDate.getTime())) throw new Error('Invalid');
} catch (e) {
  return [{ json: { ...item, skip: true, skip_reason: `Invalid date: ${item.publish_date}` } }];
}

const now = new Date();
const ukTime = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/London' }));
const ukHour = ukTime.getHours();

let windowEnd = new Date(ukTime);
windowEnd.setHours(7, 0, 0, 0);
if (ukHour < 7) windowEnd.setDate(windowEnd.getDate() - 1);

const windowStart = new Date(windowEnd);
windowStart.setDate(windowStart.getDate() - 1);

const pubTime = pubDate.getTime();
if (pubTime < windowStart.getTime() || pubTime > windowEnd.getTime()) {
  return [{ json: { ...item, skip: true, skip_reason: `Outside 24h window: ${pubDate.toISOString()}` } }];
}

return [{ json: { ...item, published_at: pubDate.toISOString() } }];

const items = $input.all().filter(i => !i.json.skip);
const seen = new Map();
const results = [];

items.sort((a, b) => (b.json.publish_date_confidence || 0) - (a.json.publish_date_confidence || 0));

for (const item of items) {
  const key = item.json.dedupe_key;
  const titleNorm = item.json.title_normalized;
  const contentFp = item.json.content_fingerprint;

  if (seen.has(key)) continue;

  let isDupe = false;
  for (const [k, ex] of seen.entries()) {
    if (ex.title_normalized === titleNorm && titleNorm.length > 20) {
      isDupe = true;
      break;
    }
    if (ex.content_fingerprint === contentFp && contentFp) {
      isDupe = true;
      break;
    }
  }

  if (!isDupe) {
    seen.set(key, item.json);
    results.push(item);
  }
}

return results;

const item = $input.first().json;

let llmData;
try {
  const content = item.message?.content || item.text || item.output || '{}';
  llmData = JSON.parse(content);
} catch (e) {
  llmData = {
    polished_title: item.original_title,
    summary: 'Summary unavailable.',
    why_matters: 'Analysis unavailable.',
    agency_relevance_score: 3
  };
}

return [{
  json: {
    ...item,
    polished_title: llmData.polished_title || item.original_title,
    summary: llmData.summary || 'Summary unavailable.',
    why_matters: llmData.why_matters || 'Analysis unavailable.',
    agency_relevance_score: parseInt(llmData.agency_relevance_score) || 3
  }
}];

const items = $input.all();
const MAX_PER_GENRE = 6;
const MAX_TOTAL = 60;

const byGenre = {};
for (const item of items) {
  const genre = item.json.genre;
  if (!byGenre[genre]) byGenre[genre] = [];
  byGenre[genre].push(item);
}

for (const genre in byGenre) {
  byGenre[genre].sort((a, b) => {
    const scoreA = a.json.agency_relevance_score || 0;
    const scoreB = b.json.agency_relevance_score || 0;
    if (scoreB !== scoreA) return scoreB - scoreA;
    return new Date(b.json.published_at || 0) - new Date(a.json.published_at || 0);
  });
}

const results = [];
let overallRank = 0;

for (const genre in byGenre) {
  const stories = byGenre[genre].slice(0, MAX_PER_GENRE);
  stories.forEach((item, idx) => {
    overallRank++;
    if (overallRank <= MAX_TOTAL) {
      results.push({
        json: {
          ...item.json,
          genre_rank: idx + 1,
          overall_rank: overallRank,
          is_top_signal: false
        }
      });
    }
  });
}

results.sort((a, b) => {
  const scoreA = a.json.agency_relevance_score || 0;
  const scoreB = b.json.agency_relevance_score || 0;
  if (scoreB !== scoreA) return scoreB - scoreA;
  return new Date(b.json.published_at) - new Date(a.json.published_at);
});

results.slice(0, 5).forEach(item => { item.json.is_top_signal = true; });

results.sort((a, b) => {
  if (a.json.genre < b.json.genre) return -1;
  if (a.json.genre > b.json.genre) return 1;
  return a.json.genre_rank - b.json.genre_rank;
});

return results;

const allStories = $input.all().map(i => i.json);
const client = $('Loop Clients').first().json;
const run = $('Create Run').first().json;

const GENRE_COLORS = {
  'Office Equipment & Technology': '#2563eb',
  'Food & Drink': '#dc2626',
  'Telecommunications & Internet': '#7c3aed',
  'Healthcare': '#059669',
  'Education': '#0891b2',
  'Tobacco & E-cigarettes': '#57534e',
  'Charity & Nonprofit': '#db2777',
  'Fashion': '#c026d3',
  'Retail': '#ea580c',
  'Professional & Business Services': '#4f46e5',
  'Property & Construction': '#ca8a04',
  'Agencies': '#0d9488',
  'Entertainment': '#e11d48',
  'Transportation & Logistics': '#1d4ed8',
  'Consumer Electronics': '#6366f1',
  'Travel & Tourism': '#0284c7',
  'Financial': '#15803d',
  'Utilities & Energy': '#a16207',
  'Leisure & Hospitality': '#be185d',
  'Media & Publishing': '#9333ea',
  'Government & Public Sector': '#1e40af',
  'Cosmetics & Personal Care': '#ec4899',
  'Home & Garden': '#65a30d',
  'Automotive': '#b91c1c',
  'Manufacturing & Industrial': '#475569',
  'Household Consumer Goods': '#d97706'
};

const topSignals = allStories.filter(s => s.is_top_signal).slice(0, 5);

const byGenre = {};
for (const story of allStories) {
  if (!byGenre[story.genre]) byGenre[story.genre] = [];
  byGenre[story.genre].push(story);
}

const today = new Date();
const dateStr = today.toLocaleDateString('en-GB', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: 'Europe/London'
});

return [{
  json: {
    client,
    run,
    dateStr,
    storyCount: allStories.length,
    topSignals,
    storiesByGenre: byGenre,
    genreColors: GENRE_COLORS,
    recipients: client.recipients || []
  }
}];

const data = $input.first().json;
const { dateStr, storyCount, topSignals, storiesByGenre, genreColors, client } = data;

const noNewsVariants = [
  "Today's scan found no stories meeting our quality criteria within the 24-hour window. We'll be back tomorrow with fresh insights.",
  "Our filters didn't surface any qualifying stories today. Sometimes quiet news days happen—we'll return tomorrow with the latest.",
  "No stories passed our quality threshold today. Rest assured, we're monitoring continuously and will deliver tomorrow's brief as usual.",
  "Today's news cycle didn't yield stories meeting our standards. We maintain strict criteria to ensure you only receive relevant, high-quality content.",
  "A rare quiet day in our monitored sources. Our automated checks continue around the clock—expect your next brief tomorrow at 07:00.",
  "No qualifying content today. Our multi-tier validation ensures quality over quantity. Tomorrow's brief will arrive on schedule.",
  "Today's sources didn't produce content meeting our publication criteria. Quality assurance remains our priority—see you tomorrow."
];

const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / (1000 * 60 * 60 * 24));
const variant = noNewsVariants[dayOfYear % noNewsVariants.length];

let html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>44 News Automation - Morning Brief</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; line-height: 1.6; color: #003d96; background-color: #f3feff; margin: 0; padding: 0; }
    .container { max-width: 680px; margin: 0 auto; padding: 20px; }
    .header { text-align: center; padding: 30px 20px; background: linear-gradient(135deg, #003d96 0%, #0056b3 100%); color: white; border-radius: 12px 12px 0 0; }
    .header h1 { margin: 0 0 10px 0; font-size: 28px; font-weight: 700; }
    .header .date { font-size: 16px; opacity: 0.9; }
    .content { background: white; padding: 30px; border-radius: 0 0 12px 12px; box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); }
    .top-signals { background: #f8fafc; border-left: 4px solid #003d96; padding: 20px; margin-bottom: 30px; border-radius: 0 8px 8px 0; }
    .top-signals h2 { margin: 0 0 15px 0; font-size: 18px; color: #003d96; }
    .top-signals ul { margin: 0; padding-left: 20px; }
    .top-signals li { margin-bottom: 8px; }
    .top-signals a { color: #003d96; text-decoration: none; }
    .top-signals a:hover { text-decoration: underline; }
    .genre-section { margin-bottom: 30px; }
    .genre-header { color: white; padding: 12px 20px; border-radius: 8px; margin-bottom: 15px; font-size: 16px; font-weight: 600; }
    .story-card { background: #f8fafc; border-radius: 8px; padding: 20px; margin-bottom: 15px; border-left: 4px solid #e2e8f0; }
    .story-card h3 { margin: 0 0 10px 0; font-size: 17px; }
    .story-card h3 a { color: #003d96; text-decoration: none; }
    .story-card h3 a:hover { text-decoration: underline; }
    .story-card .source { font-size: 12px; color: #64748b; margin-bottom: 10px; }
    .story-card .summary { font-size: 14px; color: #334155; margin-bottom: 12px; }
    .story-card .why-matters { font-size: 13px; color: #475569; background: #e0f2fe; padding: 12px; border-radius: 6px; border-left: 3px solid #0284c7; }
    .story-card .why-matters strong { color: #0369a1; }
    .footer { text-align: center; padding: 20px; color: #64748b; font-size: 12px; }
    .no-news { text-align: center; padding: 40px 20px; color: #64748b; }
    @media (max-width: 600px) { .container { padding: 10px; } .header { padding: 20px 15px; } .header h1 { font-size: 22px; } .content { padding: 20px 15px; } }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>44 News Automation</h1>
      <div class="date">Morning Brief — ${dateStr}</div>
    </div>
    <div class="content">\n`;

if (storyCount === 0) {
  html += `      <div class="no-news"><p>${variant}</p></div>\n`;
} else {
  if (topSignals.length > 0) {
    html += `      <div class="top-signals"><h2>Top Signals</h2><ul>\n`;
    for (const signal of topSignals) {
      html += `          <li><a href="${signal.canonical_url}">${signal.polished_title}</a></li>\n`;
    }
    html += `      </ul></div>\n`;
  }

  const genres = Object.keys(storiesByGenre).sort();
  for (const genre of genres) {
    const stories = storiesByGenre[genre];
    const color = genreColors[genre] || '#003d96';
    html += `      <div class="genre-section"><div class="genre-header" style="background-color: ${color};">${genre}</div>\n`;
    for (const story of stories) {
      html += `        <div class="story-card">
          <h3><a href="${story.canonical_url}">${story.polished_title}</a></h3>
          <div class="source">${story.source_name || 'Unknown'}</div>
          <div class="summary">${story.summary}</div>
          <div class="why-matters"><strong>Why this matters:</strong> ${story.why_matters}</div>
        </div>\n`;
    }
    html += `      </div>\n`;
  }
}

html += `    </div>
    <div class="footer">
      <p>Automated by 44 News Automation</p>
      <p>This email was generated automatically. Please do not reply.</p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    ...data,
    emailHtml: html,
    emailSubject: `44 News Automation — Morning Brief — ${dateStr}`,
    isNoNews: storyCount === 0,
    noNewsVariant: storyCount === 0 ? (dayOfYear % 7) + 1 : null
  }
}];

